# Code generated by Claude
"""The plan of the MPVI pipeline in the paper's segment format (design plan 8, D4 item 6), and its post-processing tags.

    plan = BEAKER_ON_HOTPLATE_PLAN                  # a hand-written plan; the LLM planner later returns the same structure
    steps = postprocess(plan)                       # the plan's segments with their tags, in order

The format is exactly the paper's: {"task_name": str, "segments": [{"type": "navigation" | "manipulation", "description": str, "completion_criteria": str,
"target": str or None}]}; `completion_criteria` is an end state, not an action; `target` is given for navigation segments only.

The post-processing tags of each manipulation segment (design plan 8): (a) the primitive it maps to ("pick" or "place") with its completion rule, and (b) whether it is the
last manipulation step before a navigation step (here also before the end of the plan), and only those steps get completion checks. Consecutive manipulation segments form
one unit whose completion criterion is the last step's. The object a primitive acts on (the "object" tag) is found in the description. The primitive and object tags are a
keyword rule here (the paper's post-processing is its own; this is the stand-in).

Contents:
    BEAKER_ON_HOTPLATE_PLAN: the hand-written plan of the test task.
    validate_plan(plan): raises ValueError with the first problem.
    postprocess(plan, objects): the tagged steps.
"""

PRIMITIVE_WORDS = {"pick": ("pick up", "pick", "grasp", "pick-up"), "place": ("place", "put", "set down")}

BEAKER_ON_HOTPLATE_PLAN = {
    "task_name": "Put the beaker on the hotplate",
    "segments": [
        {"type": "navigation", "description": "Go to the bench with the beaker and the hotplate",
         "completion_criteria": "The robot is standing at the bench in front of the beaker and the hotplate", "target": "bench"},
        {"type": "manipulation", "description": "Pick up the beaker",
         "completion_criteria": "The beaker is held in the gripper", "target": None},
        {"type": "manipulation", "description": "Place the beaker on the hotplate",
         "completion_criteria": "The beaker is standing on the hotplate and the gripper is open", "target": None},
    ],
}


def validate_plan(plan):
    """Checks that a plan has the paper's format.

    Args:
        plan (dict): The plan.

    Raises:
        ValueError: With the first problem found.
    """
    if not isinstance(plan, dict) or not isinstance(plan.get("task_name"), str) or not isinstance(plan.get("segments"), list) or not plan["segments"]:
        raise ValueError("a plan is {'task_name': str, 'segments': [at least one segment]}")
    for i, s in enumerate(plan["segments"]):
        if s.get("type") not in ("navigation", "manipulation"):
            raise ValueError(f"segment {i}: type must be 'navigation' or 'manipulation', got {s.get('type')!r}")
        if not isinstance(s.get("description"), str) or not isinstance(s.get("completion_criteria"), str):
            raise ValueError(f"segment {i}: needs a description and a completion_criteria (strings)")
        if (s["type"] == "navigation") != (s.get("target") is not None):
            raise ValueError(f"segment {i}: the target is given for navigation segments only")


def postprocess(plan, objects=("beaker", "hotplate")):
    """Tags a plan's segments for the orchestrator.

    Args:
        plan (dict): A valid plan (validate_plan).
        objects (tuple of str): Object names to look for in a manipulation description, the first one found is the primitive's object ("beaker" is the pick's object,
            and for a place the object it carries). Defaults to ("beaker", "hotplate").

    Returns:
        list[dict]: One dict per segment, in order: the segment's own keys plus "index", "primitive" ("pick" or "place", manipulation only), "object" (the first name of
        `objects` in the description, manipulation only), "group" (the number of its unit of consecutive manipulation segments, manipulation only) and "check" (bool: whether
        a completion check follows it: the last segment of its unit).

    Raises:
        ValueError: If the plan is malformed, or a manipulation description matches no primitive.
    """
    validate_plan(plan)
    steps, group = [], -1
    segs = plan["segments"]
    for i, s in enumerate(segs):
        t = {**s, "index": i, "check": False}
        if s["type"] == "manipulation":
            text = s["description"].lower()
            prim = next((p for p, words in PRIMITIVE_WORDS.items() if any(text.startswith(w) for w in words)), None)
            if prim is None:
                raise ValueError(f"segment {i}: no primitive (pick or place) found in {s['description']!r}")
            if i == 0 or segs[i - 1]["type"] != "manipulation":
                group += 1
            t.update({"primitive": prim, "object": next((o for o in objects if o in text), None), "group": group})
            t["check"] = i == len(segs) - 1 or segs[i + 1]["type"] != "manipulation"
        steps.append(t)
    return steps
